# test_lane_n4_offset_slopes.jl — lane N4 (owner decisions 6b and 7b, 11 Oct 2026).
#   #941: Poisson `offset()` + one ordinary random intercept `(1 | g)` (the rate GLMM).
#   #960: layouts drmTMB fits that DRModels.jl refused —
#         Gaussian `(1 + x | g)` mean + `sigma ~ (1 | g)`, and independent slopes
#         `(1 | g) + (0 + x | g)` for Gamma() and Student().
# Oracle numbers are drmTMB 0.7.1 (0eb0467) outputs on the own-simulated fixtures in
# test/fixtures/n4/ (generated by gen_oracle.R there; drmTMB is only run, never vendored).
# The issue-recorded ChickWeight/Owls values (-2603.204, -2306.176, -2313.485) were
# reproduced on the real data in the check-log; those datasets are not vendored here.

using DRModels
using Test
using DelimitedFiles
using LinearAlgebra: diag

function _n4_csv(name)
    m, h = readdlm(joinpath(@__DIR__, "fixtures", "n4", name), ','; header = true)
    cols = [all(x -> x isa Number, c) ? Float64.(c) : String.(string.(c)) for c in eachcol(m)]
    return NamedTuple{Tuple(Symbol.(vec(h)))}(Tuple(cols))
end

@testset "lane N4: offset + random effects, and drmTMB-parity random-slope layouts" begin
    rate = _n4_csv("rate.csv")
    grow = _n4_csv("growth.csv")

    @testset "#941 Poisson offset + (1 | g)" begin
        f = bf(@formula(y ~ 1 + x + offset(logexp) + (1 | g)))
        # TMB-convention Laplace == drmTMB's objective (logLik -560.6653865).
        fl = drm(f, Poisson(); data = rate, marginal = :Laplace)
        @test fl.converged
        @test loglik(fl) ≈ -560.6653865 atol = 1e-5
        @test coef(fl, :mu) ≈ [0.6571966, 0.2382218] atol = 1e-5
        @test exp(coef(fl, :resd)[1]) ≈ 0.5257528 atol = 1e-5
        # Default :LA (GHQ-32) integrates the same model more exactly than the Laplace objective:
        # estimates agree to the Laplace approximation error.
        fg = drm(f, Poisson(); data = rate)
        @test fg.converged
        @test coef(fg, :mu) ≈ coef(fl, :mu) atol = 5e-3
        # :AGHQ threads the offset too (subset: the full set hits a pre-existing AGHQ non-concavity
        # error with or without an offset, outside this lane).
        ix = findall(g -> parse(Int, g[2:end]) <= 15, rate.g)
        sub = (; y = rate.y[ix], x = rate.x[ix], logexp = rate.logexp[ix], g = rate.g[ix])
        fs = drm(f, Poisson(); data = sub)
        fa = drm(f, Poisson(); data = sub, marginal = :AGHQ)
        @test fs.converged && fa.converged
        @test loglik(fa) ≈ loglik(fs) atol = 1e-6
        @test coef(fa, :mu) ≈ coef(fs, :mu) atol = 1e-6
        # the offset is a fixed coefficient of 1, never an estimated column
        @test length(coef(fg, :mu)) == 2
        # fitted counts carry the exposure: λ = exposure * exp(Xβ) (b = 0)
        @test fitted(fg) ≈ exp.(rate.logexp) .* exp.(coef(fg, :mu)[1] .+ coef(fg, :mu)[2] .* rate.x)
        # the offset is not a no-op: dropping it changes the fit
        fn = drm(bf(@formula(y ~ 1 + x + (1 | g))), Poisson(); data = rate, marginal = :Laplace)
        @test abs(loglik(fn) - loglik(fl)) > 1.0
        # a zero offset reproduces the offset-free fit exactly
        z = merge(rate, (; zoff = zeros(length(rate.y))))
        fz = drm(bf(@formula(y ~ 1 + x + offset(zoff) + (1 | g))), Poisson(); data = z, marginal = :Laplace)
        @test loglik(fz) ≈ loglik(fn) atol = 1e-8
    end

    @testset "#941 refusals that remain" begin
        z = merge(rate, (; z = rate.x))
        # offset + random slope / crossed / zi / hu / VA are still refused, loudly (ArgumentError, #938)
        @test_throws ArgumentError drm(bf(@formula(y ~ 1 + x + offset(logexp) + (1 + x | g))), Poisson(); data = z)
        @test_throws ArgumentError drm(bf(@formula(y ~ 1 + x + offset(logexp) + (1 | g) + (1 | z))), Poisson(); data = z)
        @test_throws ArgumentError drm(bf(@formula(y ~ 1 + x + offset(logexp) + (1 | g))), Poisson();
                                        data = z, marginal = :VA)
        # offset + (1 | g) on another family under :Laplace is refused, not turned into a free regressor
        @test_throws ArgumentError drm(bf(@formula(y ~ 1 + x + offset(logexp) + (1 | g))), Binomial();
                                       data = z, marginal = :Laplace)
    end

    @testset "#960 Gaussian (1 + x | g) mean + sigma (1 | g)" begin
        f = bf(@formula(wgauss ~ 1 + time + diet + (1 + time | g)),
               @formula(sigma ~ 1 + time + (1 | g)))
        fit = drm(f, Gaussian(); data = grow)
        @test fit.converged
        @test loglik(fit) ≈ -275.8933672 atol = 1e-4
        @test coef(fit, :mu) ≈ [41.459124997, 59.934138016, 4.158096646] atol = 1e-3
        @test coef(fit, :sigma) ≈ [1.101150437, 0.003325529] atol = 1e-3
        @test exp(coef(fit, :resd)[1]) ≈ 0.3677230 atol = 1e-3          # sigma RI SD
        Σ = vc(fit)[:g]
        @test sqrt.(diag(Σ)) ≈ [2.2539585, 4.2699147] atol = 1e-3
        @test Σ[1, 2] / sqrt(Σ[1, 1] * Σ[2, 2]) ≈ -0.3522631 atol = 1e-3
        r = ranef(fit)
        @test size(r[:g]) == (14, 2) && length(r[:g_logsigma]) == 14
        # it contains the #745 intercept-only cell: a degenerate slope variance collapses to it
        fi = drm(bf(@formula(wgauss ~ 1 + time + diet + (1 | g)), @formula(sigma ~ 1 + time + (1 | g))),
                 Gaussian(); data = grow)
        @test loglik(fit) >= loglik(fi) - 1e-6
        # still refused: slope-only, two mean terms, different sigma group
        @test_throws ErrorException drm(bf(@formula(wgauss ~ 1 + time + (0 + time | g)), @formula(sigma ~ 1 + (1 | g))),
                                        Gaussian(); data = grow)
        @test_throws ErrorException drm(bf(@formula(wgauss ~ 1 + time + (1 | g) + (0 + time | g)), @formula(sigma ~ 1 + (1 | g))),
                                        Gaussian(); data = grow)
    end

    @testset "#960 Gamma independent slopes (1 | g) + (0 + x | g)" begin
        fit = drm(bf(@formula(wgamma ~ 1 + time + diet + (1 | g) + (0 + time | g)), @formula(sigma ~ 1)),
                  Gamma(); data = grow)
        @test fit.converged
        @test loglik(fit) ≈ -417.3726088 atol = 1e-4
        @test coef(fit, :mu) ≈ [3.5533184, 0.9624262, 0.3409130] atol = 1e-4
        @test exp(coef(fit, :sigma)[1]) ≈ 0.21139596 atol = 1e-4
        @test exp.(coef(fit, :resd)) ≈ [0.13641605, 0.06364372] atol = 1e-3
        @test fit.marginal === :Laplace
        # drmTMB refuses the correlated form for Gamma; DRModels.jl's own GHQ route still fits it
        # and is not displaced by the independent route.
        fc = drm(bf(@formula(wgamma ~ 1 + time + diet + (1 + time | g)), @formula(sigma ~ 1)), Gamma(); data = grow)
        @test isfinite(loglik(fc))
        # correlated + independent mixed in one formula stays refused
        @test_throws ErrorException drm(bf(@formula(wgamma ~ 1 + time + (1 + time | g) + (0 + time | g)), @formula(sigma ~ 1)),
                                        Gamma(); data = grow)
    end

    @testset "#960 Student independent slopes (1 | g) + (0 + x | g)" begin
        fit = drm(bf(@formula(wstud ~ 1 + time + diet + (1 | g) + (0 + time | g)), @formula(sigma ~ 1)),
                  Student(); data = grow)
        @test fit.converged
        @test loglik(fit) ≈ -264.4638655 atol = 1e-3
        @test coef(fit, :mu) ≈ [40.912908, 59.708592, 5.413951] atol = 5e-3
        @test exp(coef(fit, :sigma)[1]) ≈ exp(0.952695) atol = 5e-3
        @test coef(fit, :nu)[1] ≈ 1.851630 atol = 5e-3
        @test exp.(coef(fit, :resd)) ≈ [2.050145, 3.499140] atol = 5e-3
    end
end
